class Invoice extends DataClass implements Insertable<Invoice> {
  final int id;

  /// Numéro affiché, ex: FAC-2026-0001.
  final String numero;

  /// NULL = vente au comptoir sans client enregistré.
  final int? clientId;
  final int storeId;

  /// Renseigné si la facture provient d'un devis converti.
  final int? quoteId;
  final int userId;
  final DateTime dateCreation;
  final double totalHt;
  final double remiseGlobale;
  final double totalFinal;
  final double montantPaye;

  /// 'paye' | 'partiel' | 'non_paye'
  final String statutPaiement;
  final DateTime? dateModification;
  final int? modifieParUserId;
  const Invoice(
      {required this.id,
      required this.numero,
      this.clientId,
      required this.storeId,
      this.quoteId,
      required this.userId,
      required this.dateCreation,
      required this.totalHt,
      required this.remiseGlobale,
      required this.totalFinal,
      required this.montantPaye,
      required this.statutPaiement,
      this.dateModification,
      this.modifieParUserId});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['numero'] = Variable<String>(numero);
    if (!nullToAbsent || clientId != null) {
      map['client_id'] = Variable<int>(clientId);
    }
    map['store_id'] = Variable<int>(storeId);
    if (!nullToAbsent || quoteId != null) {
      map['quote_id'] = Variable<int>(quoteId);
    }
    map['user_id'] = Variable<int>(userId);
    map['date_creation'] = Variable<DateTime>(dateCreation);
    map['total_ht'] = Variable<double>(totalHt);
    map['remise_globale'] = Variable<double>(remiseGlobale);
    map['total_final'] = Variable<double>(totalFinal);
    map['montant_paye'] = Variable<double>(montantPaye);
    map['statut_paiement'] = Variable<String>(statutPaiement);
    if (!nullToAbsent || dateModification != null) {
      map['date_modification'] = Variable<DateTime>(dateModification);
    }
    if (!nullToAbsent || modifieParUserId != null) {
      map['modifie_par_user_id'] = Variable<int>(modifieParUserId);
    }
    return map;
  }

  InvoicesCompanion toCompanion(bool nullToAbsent) {
    return InvoicesCompanion(
      id: Value(id),
      numero: Value(numero),
      clientId: clientId == null && nullToAbsent
          ? const Value.absent()
          : Value(clientId),
      storeId: Value(storeId),
      quoteId: quoteId == null && nullToAbsent
          ? const Value.absent()
          : Value(quoteId),
      userId: Value(userId),
      dateCreation: Value(dateCreation),
      totalHt: Value(totalHt),
      remiseGlobale: Value(remiseGlobale),
      totalFinal: Value(totalFinal),
      montantPaye: Value(montantPaye),
      statutPaiement: Value(statutPaiement),
      dateModification: dateModification == null && nullToAbsent
          ? const Value.absent()
          : Value(dateModification),
      modifieParUserId: modifieParUserId == null && nullToAbsent
          ? const Value.absent()
          : Value(modifieParUserId),
    );
  }

  factory Invoice.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Invoice(
      id: serializer.fromJson<int>(json['id']),
      numero: serializer.fromJson<String>(json['numero']),
      clientId: serializer.fromJson<int?>(json['clientId']),
      storeId: serializer.fromJson<int>(json['storeId']),
      quoteId: serializer.fromJson<int?>(json['quoteId']),
      userId: serializer.fromJson<int>(json['userId']),
      dateCreation: serializer.fromJson<DateTime>(json['dateCreation']),
      totalHt: serializer.fromJson<double>(json['totalHt']),
      remiseGlobale: serializer.fromJson<double>(json['remiseGlobale']),
      totalFinal: serializer.fromJson<double>(json['totalFinal']),
      montantPaye: serializer.fromJson<double>(json['montantPaye']),
      statutPaiement: serializer.fromJson<String>(json['statutPaiement']),
      dateModification:
          serializer.fromJson<DateTime?>(json['dateModification']),
      modifieParUserId: serializer.fromJson<int?>(json['modifieParUserId']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'numero': serializer.toJson<String>(numero),
      'clientId': serializer.toJson<int?>(clientId),
      'storeId': serializer.toJson<int>(storeId),
      'quoteId': serializer.toJson<int?>(quoteId),
      'userId': serializer.toJson<int>(userId),
      'dateCreation': serializer.toJson<DateTime>(dateCreation),
      'totalHt': serializer.toJson<double>(totalHt),
