class AppSetting extends DataClass implements Insertable<AppSetting> {
  final int id;
  final String nomEntreprise;
  final String? telephone;
  final String? adresse;

  /// Chemin absolu vers le fichier logo sur le disque (PNG/JPG),
  /// copié dans le dossier de données de l'application lors de
  /// l'import pour éviter de dépendre d'un chemin externe fragile.
  final String? logoPath;
  final String? email;

  /// Courte phrase d'activité affichée sous le nom du commerce sur
  /// la facture imprimée, ex: "Pneus neufs et occasion - Vente et pose".
  final String? slogan;
  final String commentairePiedDePage;
  final String? nif;
  final String? rccm;
  final String? ifu;
  final bool tvaActive;
  final double tauxTva;
  final String devise;
  final String? signaturePath;
  final String? cachetPath;
  const AppSetting(
      {required this.id,
      required this.nomEntreprise,
      this.telephone,
      this.adresse,
      this.logoPath,
      this.email,
      this.slogan,
      required this.commentairePiedDePage,
      this.nif,
      this.rccm,
      this.ifu,
      required this.tvaActive,
      required this.tauxTva,
      required this.devise,
      this.signaturePath,
      this.cachetPath});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['nom_entreprise'] = Variable<String>(nomEntreprise);
    if (!nullToAbsent || telephone != null) {
      map['telephone'] = Variable<String>(telephone);
    }
    if (!nullToAbsent || adresse != null) {
      map['adresse'] = Variable<String>(adresse);
    }
    if (!nullToAbsent || logoPath != null) {
      map['logo_path'] = Variable<String>(logoPath);
    }
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    if (!nullToAbsent || slogan != null) {
      map['slogan'] = Variable<String>(slogan);
    }
    map['commentaire_pied_de_page'] = Variable<String>(commentairePiedDePage);
    if (!nullToAbsent || nif != null) {
      map['nif'] = Variable<String>(nif);
    }
    if (!nullToAbsent || rccm != null) {
      map['rccm'] = Variable<String>(rccm);
    }
    if (!nullToAbsent || ifu != null) {
      map['ifu'] = Variable<String>(ifu);
    }
    map['tva_active'] = Variable<bool>(tvaActive);
    map['taux_tva'] = Variable<double>(tauxTva);
    map['devise'] = Variable<String>(devise);
    if (!nullToAbsent || signaturePath != null) {
      map['signature_path'] = Variable<String>(signaturePath);
    }
    if (!nullToAbsent || cachetPath != null) {
      map['cachet_path'] = Variable<String>(cachetPath);
    }
    return map;
  }

  AppSettingsCompanion toCompanion(bool nullToAbsent) {
    return AppSettingsCompanion(
      id: Value(id),
      nomEntreprise: Value(nomEntreprise),
      telephone: telephone == null && nullToAbsent
          ? const Value.absent()
          : Value(telephone),
      adresse: adresse == null && nullToAbsent
          ? const Value.absent()
          : Value(adresse),
      logoPath: logoPath == null && nullToAbsent
          ? const Value.absent()
          : Value(logoPath),
      email:
          email == null && nullToAbsent ? const Value.absent() : Value(email),
      slogan:
          slogan == null && nullToAbsent ? const Value.absent() : Value(slogan),
      commentairePiedDePage: Value(commentairePiedDePage),
      nif: nif == null && nullToAbsent ? const Value.absent() : Value(nif),
      rccm: rccm == null && nullToAbsent ? const Value.absent() : Value(rccm),
      ifu: ifu == null && nullToAbsent ? const Value.absent() : Value(ifu),
      tvaActive: Value(tvaActive),
      tauxTva: Value(tauxTva),
      devise: Value(devise),
      signaturePath: signaturePath == null && nullToAbsent
          ? const Value.absent()
          : Value(signaturePath),
      cachetPath: cachetPath == null && nullToAbsent
          ? const Value.absent()
          : Value(cachetPath),
    );
  }

  factory AppSetting.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return AppSetting(
      id: serializer.fromJson<int>(json['id']),
      nomEntreprise: serializer.fromJson<String>(json['nomEntreprise']),
      telephone: serializer.fromJson<String?>(json['telephone']),
      adresse: serializer.fromJson<String?>(json['adresse']),
      logoPath: serializer.fromJson<String?>(json['logoPath']),
      email: serializer.fromJson<String?>(json['email']),
      slogan: serializer.fromJson<String?>(json['slogan']),
      commentairePiedDePage:
          serializer.fromJson<String>(json['commentairePiedDePage']),
      nif: serializer.fromJson<String?>(json['nif']),
      rccm: serializer.fromJson<String?>(json['rccm']),
      ifu: serializer.fromJson<String?>(json['ifu']),
      tvaActive: serializer.fromJson<bool>(json['tvaActive']),
      tauxTva: serializer.fromJson<double>(json['tauxTva']),
      devise: serializer.fromJson<String>(json['devise']),
      signaturePath: serializer.fromJson<String?>(json['signaturePath']),
      cachetPath: serializer.fromJson<String?>(json['cachetPath']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'nomEntreprise': serializer.toJson<String>(nomEntreprise),
      'telephone': serializer.toJson<String?>(telephone),
      'adresse': serializer.toJson<String?>(adresse),
      'logoPath': serializer.toJson<String?>(logoPath),
      'email': serializer.toJson<String?>(email),
      'slogan': serializer.toJson<String?>(slogan),
      'commentairePiedDePage': serializer.toJson<String>(commentairePiedDePage),
      'nif': serializer.toJson<String?>(nif),
      'rccm': serializer.toJson<String?>(rccm),
      'ifu': serializer.toJson<String?>(ifu),
      'tvaActive': serializer.toJson<bool>(tvaActive),
      'tauxTva': serializer.toJson<double>(tauxTva),
      'devise': serializer.toJson<String>(devise),
      'signaturePath': serializer.toJson<String?>(signaturePath),
      'cachetPath': serializer.toJson<String?>(cachetPath),
    };
  }

  AppSetting copyWith(
          {int? id,
          String? nomEntreprise,
          Value<String?> telephone = const Value.absent(),
          Value<String?> adresse = const Value.absent(),
          Value<String?> logoPath = const Value.absent(),
          Value<String?> email = const Value.absent(),
          Value<String?> slogan = const Value.absent(),
          String? commentairePiedDePage,
          Value<String?> nif = const Value.absent(),
          Value<String?> rccm = const Value.absent(),
          Value<String?> ifu = const Value.absent(),
          bool? tvaActive,
          double? tauxTva,
          String? devise,
          Value<String?> signaturePath = const Value.absent(),
          Value<String?> cachetPath = const Value.absent()}) =>
      AppSetting(
        id: id ?? this.id,
        nomEntreprise: nomEntreprise ?? this.nomEntreprise,
        telephone: telephone.present ? telephone.value : this.telephone,
        adresse: adresse.present ? adresse.value : this.adresse,
        logoPath: logoPath.present ? logoPath.value : this.logoPath,
        email: email.present ? email.value : this.email,
        slogan: slogan.present ? slogan.value : this.slogan,
        commentairePiedDePage:
            commentairePiedDePage ?? this.commentairePiedDePage,
        nif: nif.present ? nif.value : this.nif,
        rccm: rccm.present ? rccm.value : this.rccm,
        ifu: ifu.present ? ifu.value : this.ifu,
        tvaActive: tvaActive ?? this.tvaActive,
        tauxTva: tauxTva ?? this.tauxTva,
        devise: devise ?? this.devise,
        signaturePath:
            signaturePath.present ? signaturePath.value : this.signaturePath,
        cachetPath: cachetPath.present ? cachetPath.value : this.cachetPath,
      );
  AppSetting copyWithCompanion(AppSettingsCompanion data) {
    return AppSetting(
      id: data.id.present ? data.id.value : this.id,
      nomEntreprise: data.nomEntreprise.present
          ? data.nomEntreprise.value
          : this.nomEntreprise,
      telephone: data.telephone.present ? data.telephone.value : this.telephone,
      adresse: data.adresse.present ? data.adresse.value : this.adresse,
      logoPath: data.logoPath.present ? data.logoPath.value : this.logoPath,
      email: data.email.present ? data.email.value : this.email,
      slogan: data.slogan.present ? data.slogan.value : this.slogan,
      commentairePiedDePage: data.commentairePiedDePage.present
          ? data.commentairePiedDePage.value
          : this.commentairePiedDePage,
      nif: data.nif.present ? data.nif.value : this.nif,
      rccm: data.rccm.present ? data.rccm.value : this.rccm,
      ifu: data.ifu.present ? data.ifu.value : this.ifu,
      tvaActive: data.tvaActive.present ? data.tvaActive.value : this.tvaActive,
      tauxTva: data.tauxTva.present ? data.tauxTva.value : this.tauxTva,
      devise: data.devise.present ? data.devise.value : this.devise,
      signaturePath: data.signaturePath.present
          ? data.signaturePath.value
          : this.signaturePath,
      cachetPath:
          data.cachetPath.present ? data.cachetPath.value : this.cachetPath,
    );
  }

  @override
  String toString() {
    return (StringBuffer('AppSetting(')
          ..write('id: $id, ')
          ..write('nomEntreprise: $nomEntreprise, ')
          ..write('telephone: $telephone, ')
          ..write('adresse: $adresse, ')
          ..write('logoPath: $logoPath, ')
          ..write('email: $email, ')
          ..write('slogan: $slogan, ')
          ..write('commentairePiedDePage: $commentairePiedDePage, ')
          ..write('nif: $nif, ')
          ..write('rccm: $rccm, ')
          ..write('ifu: $ifu, ')
          ..write('tvaActive: $tvaActive, ')
          ..write('tauxTva: $tauxTva, ')
          ..write('devise: $devise, ')
          ..write('signaturePath: $signaturePath, ')
          ..write('cachetPath: $cachetPath')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
      id,
      nomEntreprise,
      telephone,
      adresse,
      logoPath,
      email,
      slogan,
      commentairePiedDePage,
      nif,
      rccm,
      ifu,
      tvaActive,
      tauxTva,
      devise,
      signaturePath,
      cachetPath);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is AppSetting &&
          other.id == this.id &&
          other.nomEntreprise == this.nomEntreprise &&
          other.telephone == this.telephone &&
          other.adresse == this.adresse &&
          other.logoPath == this.logoPath &&
          other.email == this.email &&
          other.slogan == this.slogan &&
          other.commentairePiedDePage == this.commentairePiedDePage &&
          other.nif == this.nif &&
          other.rccm == this.rccm &&
          other.ifu == this.ifu &&
          other.tvaActive == this.tvaActive &&
          other.tauxTva == this.tauxTva &&
          other.devise == this.devise &&
          other.signaturePath == this.signaturePath &&
          other.cachetPath == this.cachetPath);
}

