class CommercialDocument extends DataClass
    implements Insertable<CommercialDocument> {
  final int id;

  /// Numéro affiché, ex: PRO-2026-0001, BL-2026-0003, FAC-2026-0010.
  final String numero;

  /// Type de la pièce. Valeurs possibles :
  /// 'proforma' | 'bon_commande' | 'preparation_livraison' |
  /// 'bon_livraison' | 'bon_retour' | 'avoir' |
  /// 'facture' | 'facture_comptabilisee'
  final String type;

  /// Cycle de vie du document.
  /// 'brouillon' → modifiable
  /// 'valide'    → verrouillé (impact stock possible)
  /// 'transforme'→ utilisé pour créer la pièce suivante
  /// 'annule'    → sans effet comptable
  final String statut;

  /// NULL = vente au comptoir sans client enregistré.
  final int? clientId;
  final int storeId;

  /// Date visible sur le document imprimé.
  final DateTime dateDocument;
  final DateTime dateCreation;
  final DateTime? dateModification;

  /// Renseigné quand statut passe à 'valide'.
  final DateTime? dateValidation;

  /// Échéance de paiement pour les factures.
  final DateTime? dateEcheance;
  final int? createdById;
  final int? updatedById;

  /// Dénormalisé pour l'audit (nom conservé même si l'utilisateur est supprimé).
  final String? createdByNom;
  final String? updatedByNom;
  final double totalHt;
  final double totalTva;
  final double totalTtc;
  final double remiseGlobalePct;
  final double montantPaye;

  /// 'non_paye' | 'partiel' | 'paye'
  final String statutPaiement;

  /// Pointe vers le document source (ex: un BL pointe vers son BC).
  /// Relation gérée en code ; pas de FK déclarée pour éviter la circularité
  /// dans la définition Drift.
  final int? parentDocumentId;
  final String? notes;

  /// N° BC client, référence Sage, etc.
  final String? referenceExterne;

  /// Ex: '30 jours fin de mois', 'À réception'.
  final String? conditionsReglement;

  /// Commercial (employé) à qui attribuer la commission de cette vente,
  /// choisi librement dans une liste déroulante au moment de la vente —
  /// indépendant de l'utilisateur connecté ([createdById]). Null pour
  /// une vente comptoir sans commercial (comportement inchangé).
  final int? vendeurEmployeeId;
  const CommercialDocument(
      {required this.id,
      required this.numero,
      required this.type,
      required this.statut,
      this.clientId,
      required this.storeId,
      required this.dateDocument,
      required this.dateCreation,
      this.dateModification,
      this.dateValidation,
      this.dateEcheance,
      this.createdById,
      this.updatedById,
      this.createdByNom,
      this.updatedByNom,
      required this.totalHt,
      required this.totalTva,
      required this.totalTtc,
      required this.remiseGlobalePct,
      required this.montantPaye,
      required this.statutPaiement,
      this.parentDocumentId,
      this.notes,
      this.referenceExterne,
      this.conditionsReglement,
      this.vendeurEmployeeId});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['numero'] = Variable<String>(numero);
    map['type'] = Variable<String>(type);
    map['statut'] = Variable<String>(statut);
    if (!nullToAbsent || clientId != null) {
      map['client_id'] = Variable<int>(clientId);
    }
    map['store_id'] = Variable<int>(storeId);
    map['date_document'] = Variable<DateTime>(dateDocument);
    map['date_creation'] = Variable<DateTime>(dateCreation);
    if (!nullToAbsent || dateModification != null) {
      map['date_modification'] = Variable<DateTime>(dateModification);
    }
    if (!nullToAbsent || dateValidation != null) {
      map['date_validation'] = Variable<DateTime>(dateValidation);
    }
    if (!nullToAbsent || dateEcheance != null) {
      map['date_echeance'] = Variable<DateTime>(dateEcheance);
    }
    if (!nullToAbsent || createdById != null) {
      map['created_by_id'] = Variable<int>(createdById);
    }
    if (!nullToAbsent || updatedById != null) {
      map['updated_by_id'] = Variable<int>(updatedById);
    }
    if (!nullToAbsent || createdByNom != null) {
      map['created_by_nom'] = Variable<String>(createdByNom);
    }
    if (!nullToAbsent || updatedByNom != null) {
      map['updated_by_nom'] = Variable<String>(updatedByNom);
    }
    map['total_ht'] = Variable<double>(totalHt);
    map['total_tva'] = Variable<double>(totalTva);
