class DocumentLine extends DataClass implements Insertable<DocumentLine> {
  final int id;

  /// ON DELETE CASCADE : la suppression du document supprime ses lignes.
  final int documentId;
  final int articleId;

  /// Valeurs figées au moment de la saisie (historique immuable).
  final String articleCode;
  final String articleNom;
  final double quantite;
  final double prixUnitaireHt;

  /// Taux TVA en % (ex: 0.0, 18.0). Copié depuis l'article au moment
  /// de la saisie pour permettre la modification ultérieure sans impact.
  final double tauxTva;
  final double remiseLignePct;
  final double totalHt;
  final double montantTva;
  final double totalTtc;

  /// Ordre d'affichage dans le document.
  final int position;
  final String? notesLigne;
  final double? commissionUnitaire;
  final double? commissionMontant;

  /// Renseigné une seule fois, au règlement de la commission — empêche
  /// tout double paiement par construction (voir [CommissionSettlements]).
  final int? commissionSettlementId;

  /// Promotion active au moment de la saisie de cette ligne, si son
  /// prix a été préremplié automatiquement par une promotion (voir
  /// [DocumentLinesEditor]). Snapshot figé — une modification ou
  /// suppression ultérieure de la promotion n'affecte pas les ventes
  /// déjà enregistrées. Sert au calcul de performance d'une promotion
  /// (quantité vendue, chiffre d'affaires, marge perdue).
  final int? promotionId;
  const DocumentLine(
      {required this.id,
      required this.documentId,
      required this.articleId,
      required this.articleCode,
      required this.articleNom,
      required this.quantite,
      required this.prixUnitaireHt,
      required this.tauxTva,
      required this.remiseLignePct,
      required this.totalHt,
      required this.montantTva,
      required this.totalTtc,
      required this.position,
      this.notesLigne,
      this.commissionUnitaire,
      this.commissionMontant,
      this.commissionSettlementId,
      this.promotionId});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['document_id'] = Variable<int>(documentId);
    map['article_id'] = Variable<int>(articleId);
    map['article_code'] = Variable<String>(articleCode);
    map['article_nom'] = Variable<String>(articleNom);
    map['quantite'] = Variable<double>(quantite);
    map['prix_unitaire_ht'] = Variable<double>(prixUnitaireHt);
    map['taux_tva'] = Variable<double>(tauxTva);
    map['remise_ligne_pct'] = Variable<double>(remiseLignePct);
    map['total_ht'] = Variable<double>(totalHt);
    map['montant_tva'] = Variable<double>(montantTva);
    map['total_ttc'] = Variable<double>(totalTtc);
    map['position'] = Variable<int>(position);
    if (!nullToAbsent || notesLigne != null) {
      map['notes_ligne'] = Variable<String>(notesLigne);
    }
    if (!nullToAbsent || commissionUnitaire != null) {
      map['commission_unitaire'] = Variable<double>(commissionUnitaire);
    }
    if (!nullToAbsent || commissionMontant != null) {
      map['commission_montant'] = Variable<double>(commissionMontant);
    }
    if (!nullToAbsent || commissionSettlementId != null) {
      map['commission_settlement_id'] = Variable<int>(commissionSettlementId);
    }
    if (!nullToAbsent || promotionId != null) {
      map['promotion_id'] = Variable<int>(promotionId);
    }
    return map;
  }

  DocumentLinesCompanion toCompanion(bool nullToAbsent) {
    return DocumentLinesCompanion(
      id: Value(id),
      documentId: Value(documentId),
      articleId: Value(articleId),
      articleCode: Value(articleCode),
      articleNom: Value(articleNom),
      quantite: Value(quantite),
      prixUnitaireHt: Value(prixUnitaireHt),
      tauxTva: Value(tauxTva),
      remiseLignePct: Value(remiseLignePct),
      totalHt: Value(totalHt),
      montantTva: Value(montantTva),
      totalTtc: Value(totalTtc),
      position: Value(position),
      notesLigne: notesLigne == null && nullToAbsent
          ? const Value.absent()
          : Value(notesLigne),
      commissionUnitaire: commissionUnitaire == null && nullToAbsent
          ? const Value.absent()
          : Value(commissionUnitaire),
      commissionMontant: commissionMontant == null && nullToAbsent
          ? const Value.absent()
          : Value(commissionMontant),
      commissionSettlementId: commissionSettlementId == null && nullToAbsent
          ? const Value.absent()
          : Value(commissionSettlementId),
      promotionId: promotionId == null && nullToAbsent
          ? const Value.absent()
          : Value(promotionId),
    );
  }

  factory DocumentLine.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return DocumentLine(
      id: serializer.fromJson<int>(json['id']),
      documentId: serializer.fromJson<int>(json['documentId']),
      articleId: serializer.fromJson<int>(json['articleId']),
      articleCode: serializer.fromJson<String>(json['articleCode']),
      articleNom: serializer.fromJson<String>(json['articleNom']),
      quantite: serializer.fromJson<double>(json['quantite']),
      prixUnitaireHt: serializer.fromJson<double>(json['prixUnitaireHt']),
      tauxTva: serializer.fromJson<double>(json['tauxTva']),
      remiseLignePct: serializer.fromJson<double>(json['remiseLignePct']),
      totalHt: serializer.fromJson<double>(json['totalHt']),
      montantTva: serializer.fromJson<double>(json['montantTva']),
      totalTtc: serializer.fromJson<double>(json['totalTtc']),
      position: serializer.fromJson<int>(json['position']),
      notesLigne: serializer.fromJson<String?>(json['notesLigne']),
      commissionUnitaire:
          serializer.fromJson<double?>(json['commissionUnitaire']),
      commissionMontant:
          serializer.fromJson<double?>(json['commissionMontant']),
      commissionSettlementId:
          serializer.fromJson<int?>(json['commissionSettlementId']),
      promotionId: serializer.fromJson<int?>(json['promotionId']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'documentId': serializer.toJson<int>(documentId),
      'articleId': serializer.toJson<int>(articleId),
      'articleCode': serializer.toJson<String>(articleCode),
      'articleNom': serializer.toJson<String>(articleNom),
      'quantite': serializer.toJson<double>(quantite),
      'prixUnitaireHt': serializer.toJson<double>(prixUnitaireHt),
      'tauxTva': serializer.toJson<double>(tauxTva),
      'remiseLignePct': serializer.toJson<double>(remiseLignePct),
      'totalHt': serializer.toJson<double>(totalHt),
      'montantTva': serializer.toJson<double>(montantTva),
      'totalTtc': serializer.toJson<double>(totalTtc),
      'position': serializer.toJson<int>(position),
      'notesLigne': serializer.toJson<String?>(notesLigne),
      'commissionUnitaire': serializer.toJson<double?>(commissionUnitaire),
      'commissionMontant': serializer.toJson<double?>(commissionMontant),
      'commissionSettlementId': serializer.toJson<int?>(commissionSettlementId),
      'promotionId': serializer.toJson<int?>(promotionId),
    };
  }

  DocumentLine copyWith(
          {int? id,
          int? documentId,
          int? articleId,
          String? articleCode,
          String? articleNom,
          double? quantite,
          double? prixUnitaireHt,
          double? tauxTva,
          double? remiseLignePct,
          double? totalHt,
          double? montantTva,
          double? totalTtc,
          int? position,
          Value<String?> notesLigne = const Value.absent(),
          Value<double?> commissionUnitaire = const Value.absent(),
          Value<double?> commissionMontant = const Value.absent(),
          Value<int?> commissionSettlementId = const Value.absent(),
          Value<int?> promotionId = const Value.absent()}) =>
      DocumentLine(
        id: id ?? this.id,
        documentId: documentId ?? this.documentId,
        articleId: articleId ?? this.articleId,
        articleCode: articleCode ?? this.articleCode,
        articleNom: articleNom ?? this.articleNom,
        quantite: quantite ?? this.quantite,
        prixUnitaireHt: prixUnitaireHt ?? this.prixUnitaireHt,
        tauxTva: tauxTva ?? this.tauxTva,
        remiseLignePct: remiseLignePct ?? this.remiseLignePct,
        totalHt: totalHt ?? this.totalHt,
        montantTva: montantTva ?? this.montantTva,
        totalTtc: totalTtc ?? this.totalTtc,
        position: position ?? this.position,
        notesLigne: notesLigne.present ? notesLigne.value : this.notesLigne,
        commissionUnitaire: commissionUnitaire.present
            ? commissionUnitaire.value
            : this.commissionUnitaire,
        commissionMontant: commissionMontant.present
            ? commissionMontant.value
            : this.commissionMontant,
        commissionSettlementId: commissionSettlementId.present
