class DocumentPayment extends DataClass implements Insertable<DocumentPayment> {
  final int id;
  final int documentId;
  final double montant;
  final DateTime datePaiement;

  /// 'especes' | 'cheque' | 'virement' | 'mobile_money' | 'avoir'
  final String modePaiement;

  /// N° chèque, référence mobile money, etc.
  final String? reference;

  /// Si mode = 'avoir', pointe vers l'avoir utilisé pour ce règlement.
  final int? avoirDocumentId;
  final int? createdById;

  /// Dénormalisé pour l'audit.
  final String? createdByNom;
  final DateTime dateCreation;

  /// Numéro du reçu de paiement généré pour ce règlement (ex: REC-2026-0001).
  final String? numeroRecu;
  const DocumentPayment(
      {required this.id,
      required this.documentId,
      required this.montant,
      required this.datePaiement,
      required this.modePaiement,
      this.reference,
      this.avoirDocumentId,
      this.createdById,
      this.createdByNom,
      required this.dateCreation,
      this.numeroRecu});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['document_id'] = Variable<int>(documentId);
    map['montant'] = Variable<double>(montant);
    map['date_paiement'] = Variable<DateTime>(datePaiement);
    map['mode_paiement'] = Variable<String>(modePaiement);
    if (!nullToAbsent || reference != null) {
      map['reference'] = Variable<String>(reference);
    }
    if (!nullToAbsent || avoirDocumentId != null) {
      map['avoir_document_id'] = Variable<int>(avoirDocumentId);
    }
    if (!nullToAbsent || createdById != null) {
      map['created_by_id'] = Variable<int>(createdById);
    }
    if (!nullToAbsent || createdByNom != null) {
      map['created_by_nom'] = Variable<String>(createdByNom);
    }
    map['date_creation'] = Variable<DateTime>(dateCreation);
    if (!nullToAbsent || numeroRecu != null) {
      map['numero_recu'] = Variable<String>(numeroRecu);
    }
    return map;
  }

  DocumentPaymentsCompanion toCompanion(bool nullToAbsent) {
    return DocumentPaymentsCompanion(
      id: Value(id),
      documentId: Value(documentId),
      montant: Value(montant),
      datePaiement: Value(datePaiement),
      modePaiement: Value(modePaiement),
      reference: reference == null && nullToAbsent
          ? const Value.absent()
          : Value(reference),
      avoirDocumentId: avoirDocumentId == null && nullToAbsent
          ? const Value.absent()
          : Value(avoirDocumentId),
      createdById: createdById == null && nullToAbsent
          ? const Value.absent()
          : Value(createdById),
      createdByNom: createdByNom == null && nullToAbsent
          ? const Value.absent()
          : Value(createdByNom),
      dateCreation: Value(dateCreation),
      numeroRecu: numeroRecu == null && nullToAbsent
          ? const Value.absent()
          : Value(numeroRecu),
    );
  }

