    this.rowid = const Value.absent(),
  });
  DraftsCompanion.insert({
    required String type,
    required String donnees,
    this.dateSauvegarde = const Value.absent(),
    this.rowid = const Value.absent(),
  })  : type = Value(type),
        donnees = Value(donnees);
  static Insertable<Draft> custom({
    Expression<String>? type,
    Expression<String>? donnees,
    Expression<DateTime>? dateSauvegarde,
    Expression<int>? rowid,
  }) {
    return RawValuesInsertable({
      if (type != null) 'type': type,
      if (donnees != null) 'donnees': donnees,
      if (dateSauvegarde != null) 'date_sauvegarde': dateSauvegarde,
      if (rowid != null) 'rowid': rowid,
