class InventoryLine extends DataClass implements Insertable<InventoryLine> {
  final int id;
  final int inventoryId;

  /// Null si le code lu à l'import ne correspond à aucun article
  /// connu (voir [introuvable]).
  final int? articleId;
  final String articleCode;
  final String articleNom;
  final String? categorieNom;
  final double stockTheorique;

  /// Null tant que la ligne n'a pas été comptée (ni import, ni saisie
  /// manuelle).
  final double? stockPhysique;

  /// stockPhysique - stockTheorique. Null tant que non compté.
  final double? ecart;
  final String? observation;

  /// Vrai si cette ligne provient d'un import dont le code ne
  /// correspondait à aucun article du catalogue.
  final bool introuvable;
  const InventoryLine(
      {required this.id,
      required this.inventoryId,
      this.articleId,
      required this.articleCode,
      required this.articleNom,
      this.categorieNom,
      required this.stockTheorique,
      this.stockPhysique,
      this.ecart,
      this.observation,
      required this.introuvable});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['inventory_id'] = Variable<int>(inventoryId);
    if (!nullToAbsent || articleId != null) {
      map['article_id'] = Variable<int>(articleId);
    }
    map['article_code'] = Variable<String>(articleCode);
    map['article_nom'] = Variable<String>(articleNom);
    if (!nullToAbsent || categorieNom != null) {
      map['categorie_nom'] = Variable<String>(categorieNom);
    }
    map['stock_theorique'] = Variable<double>(stockTheorique);
    if (!nullToAbsent || stockPhysique != null) {
      map['stock_physique'] = Variable<double>(stockPhysique);
    }
    if (!nullToAbsent || ecart != null) {
      map['ecart'] = Variable<double>(ecart);
    }
    if (!nullToAbsent || observation != null) {
      map['observation'] = Variable<String>(observation);
    }
    map['introuvable'] = Variable<bool>(introuvable);
    return map;
  }

  InventoryLinesCompanion toCompanion(bool nullToAbsent) {
    return InventoryLinesCompanion(
      id: Value(id),
      inventoryId: Value(inventoryId),
      articleId: articleId == null && nullToAbsent
          ? const Value.absent()
          : Value(articleId),
      articleCode: Value(articleCode),
      articleNom: Value(articleNom),
      categorieNom: categorieNom == null && nullToAbsent
          ? const Value.absent()
          : Value(categorieNom),
      stockTheorique: Value(stockTheorique),
      stockPhysique: stockPhysique == null && nullToAbsent
          ? const Value.absent()
          : Value(stockPhysique),
      ecart:
