    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'inventoryId': serializer.toJson<int>(inventoryId),
      'articleId': serializer.toJson<int?>(articleId),
      'articleCode': serializer.toJson<String>(articleCode),
      'articleNom': serializer.toJson<String>(articleNom),
      'categorieNom': serializer.toJson<String?>(categorieNom),
      'stockTheorique': serializer.toJson<double>(stockTheorique),
      'stockPhysique': serializer.toJson<double?>(stockPhysique),
      'ecart': serializer.toJson<double?>(ecart),
      'observation': serializer.toJson<String?>(observation),
      'introuvable': serializer.toJson<bool>(introuvable),
    };
