                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.supplierId,
                    referencedTable:
                        $$LoadingsTableReferences._supplierIdTable(db),
                    referencedColumn:
                        $$LoadingsTableReferences._supplierIdTable(db).id,
